# owner: platform
import unittest

from hourglass.gaps import gap_labels
from hourglass.parsing import parse_span

OPENING = parse_span("09:00-17:00")

class GapLabelTests(unittest.TestCase):
    def test_no_work_is_one_gap_for_the_day(self):
        self.assertEqual(
            gap_labels([], OPENING),
            ["gap 09:00-17:00 (480 min)"],
        )

    def test_fully_covered_has_no_gaps(self):
        worked = [parse_span("09:00-17:00")]
        self.assertEqual(gap_labels(worked, OPENING), [])

    def test_lunch_gap_between_two_shifts(self):
        worked = [
            parse_span("09:00-12:00"),
            parse_span("13:00-17:00"),
        ]
        self.assertEqual(
            gap_labels(worked, OPENING),
            ["gap 12:00-13:00 (60 min)"],
        )

    def test_several_gaps_in_order(self):
        worked = [
            parse_span("10:00-11:00"),
            parse_span("12:00-13:00"),
        ]
        self.assertEqual(
            gap_labels(worked, OPENING),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 11:00-12:00 (60 min)",
                "gap 13:00-17:00 (240 min)",
            ],
        )

    def test_overlaps_leave_no_false_gap(self):
        worked = [
            parse_span("09:00-12:00"),
            parse_span("11:00-12:30"),
            parse_span("12:30-15:00"),
        ]
        self.assertEqual(
            gap_labels(worked, OPENING),
            ["gap 15:00-17:00 (120 min)"],
        )

    def test_gap_at_the_end_of_opening_hours(self):
        worked = [parse_span("09:00-15:00")]
        self.assertEqual(
            gap_labels(worked, OPENING),
            ["gap 15:00-17:00 (120 min)"],
        )

    def test_work_before_opening_raises(self):
        worked = [parse_span("08:00-10:00")]
        with self.assertRaises(ValueError):
            gap_labels(worked, OPENING)

    def test_work_after_closing_raises(self):
        worked = [parse_span("16:00-18:00")]
        with self.assertRaises(ValueError):
            gap_labels(worked, OPENING)
